declarations.type:
∀ {u : Real} {round : Real → Real} {InRange : Real → Prop}
  {relative_round :
    ∀ (x : Real),
      InRange x →
        ∃ δ, And (LE.le.{0} (abs.{0} δ) u) (Eq.{1} (round x) (HMul.hMul.{0, 0, 0} x (HAdd.hAdd.{0, 0, 0} 1 δ)))}
  {round_1 : Real → Real} {InRange_1 : Real → Prop}
  {relative_round_1 :
    ∀ (x : Real),
      InRange_1 x →
        ∃ δ, And (LE.le.{0} (abs.{0} δ) u) (Eq.{1} (round_1 x) (HMul.hMul.{0, 0, 0} x (HAdd.hAdd.{0, 0, 0} 1 δ)))},
  Eq.{1} { round := round, InRange := InRange, relative_round := relative_round }
      { round := round_1, InRange := InRange_1, relative_round := relative_round_1 } →
    And (Eq.{1} round round_1) (Eq.{1} InRange InRange_1)

